/// Executable analogue of the recursive spec: convert a sequence (slice) to a set
/// by recursively dropping the last element and inserting it.
///
/// This is implemented iteratively to avoid recursion depth issues, but matches the
/// intended recursion:
/// - base: empty -> empty set
/// - step: set(seq[..len-1]) with seq[len-1] inserted
pub fn seq_to_set_rec_i32(seq: &[i32]) -> HashSet<i32> {
    // Equivalent to: fold over elements inserting into a set.
    let mut set = HashSet::new();
    for &x in seq {
        set.insert(x);
    }
    set
}

/// Checks the “membership equivalence” property:
/// `x` is in `seq` iff `x` is in `seq_to_set_rec_i32(seq)`.
pub fn seq_to_set_rec_contains_i32(seq: &[i32], x: i32) -> bool {
    let set = seq_to_set_rec_i32(seq);
    let in_seq = seq.iter().any(|&y| y == x);
    let in_set = set.contains(&x);
    in_seq == in_set
}

/// Checks that the recursive-set construction equals the “comprehension” set
/// (here: inserting all elements). In Rust these are the same construction, so this
/// is trivially true; we express it as set equality.
pub fn seq_to_set_equal_rec_i32(seq: &[i32]) -> bool {
    let a = seq_to_set_rec_i32(seq);
    let b = seq.iter().copied().collect::<HashSet<i32>>();
    a == b
}

/// Checks the “push corresponds to insert” lemma:
/// set(s ++ [val]) == set(s) ∪ {val}
pub fn lemma_seq_push_to_set_insert_i32(s: &[i32], val: i32) -> bool {
    let mut pushed = s.to_vec();
    pushed.push(val);

    let left = seq_to_set_rec_i32(&pushed);

    let mut right = seq_to_set_rec_i32(s);
    right.insert(val);

    left == right
}

